// Test 7: Anon user cannot access non-public events
await test("Anon cannot see draft events in public_events", async () => {
  const { data } = await supabase
    .from('public_events')
    .select('id, status')
    .eq('status', 'draft')
    .limit(1);
  // RLS should filter out drafts - data should be empty
  assert(!data || data.length === 0, "Draft events should not be visible via public_events view");
});

// Test 8: Ticket availability returns structured response
await test("get_ticket_availability returns structured response", async () => {
  // Get a real published event if available
  const { data: events } = await supabase
    .from('public_events')
    .select('id')
    .eq('status', 'published')
    .limit(1);

  if (events && events.length > 0) {
    const { data } = await supabase.rpc('get_ticket_availability', {
      _event_id: events[0].id
    });
    // Should have ticket_types array (even if empty)
    assert(
      data && (data.ticket_types !== undefined || data.error),
      "Should return ticket_types array or error"
    );
  } else {
    // No published events - test with fake ID
    const { data } = await supabase.rpc('get_ticket_availability', {
      _event_id: '00000000-0000-0000-0000-000000000000'
    });
    // Should get error response, not crash
    assert(data !== undefined, "Should return a response");
  }
});

// Test 9: validate_ticket_order with empty items returns NO_ITEMS
await test("validate_ticket_order rejects empty items", async () => {
  const { data: events } = await supabase
    .from('public_events')
    .select('id')
    .eq('status', 'published')
    .limit(1);

  if (events && events.length > 0) {
    const { data } = await supabase.rpc('validate_ticket_order', {
      _event_id: events[0].id,
      _items: []
    });
    assert(
      data && (!data.valid || data.errors?.some(e => e.error === 'NO_ITEMS')),
      "Should reject empty items"
    );
  }
  // If no events, we already tested the RPC exists in test 3
});

